{
  "a_sentences": [
    {
      "a_text": "Das Bundesgericht hält fest, dass die Vorinstanz die gesetzlichen Bestimmungen und die Rechtsprechung zur Invaliditätsbegriffsbestimmung sowie zur Invaliditätsbemessung vollständig und korrekt wiedergegeben hat.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Nach Art. 17 Abs. 1 IVG hat die Versicherte Anspruch auf Umschulung in eine neue Erwerbstätigkeit, wenn ihre Invalidität diese Massnahme notwendig macht und dadurch ihre Erwerbsfähigkeit voraussichtlich erhalten oder verbessert werden kann.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Die Vorinstanz erwog zutreffend, dass sich die approximative Gleichwertigkeit der Tätigkeiten nicht primär nach dem Ausbildungsniveau, sondern nach den nach der Eingliederung zu erwartenden Erwerbsmöglichkeiten bemisst.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Eine zusätzliche Umschulung ist nur erforderlich, wenn die bereits gewährte Ausbildung kein genügendes Einkommen verschafft und weitere Massnahmen nötig sind, um ein mit der früheren Tätigkeit vergleichbares Einkommen zu erzielen.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Für die Zeit vom 1. August 2012 bis 31. Dezember 2012 wurde der Invaliditätsgrad auf 60 % festgesetzt und ein Anspruch auf eine Dreiviertelsrente bestätigt.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Ab 1. April 2019 verneinte die Vorinstanz einen Rentenanspruch, da der Invaliditätsgrad auf 38 % festgesetzt wurde und damit unter der Schwelle für eine Invalidenrente liegt.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Das Bundesgericht bestätigt, dass der Invaliditätsgrad unabhängig davon, ob die Tätigkeit als Spezialistin in der beruflichen Eingliederung oder als Sozialarbeiterin angenommen wird, zum gleichen Ergebnis führt.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Die Vorinstanz stellte fest, dass die Versicherte bereits einen CAS als Spezialistin in der beruflichen Eingliederung sowie ein Zertifikat als Erwachsenenbildnerin erhalten hat, was sie nicht bestreitet.",
      "b_propositions": ["P8"]
    }
  ]
}
